// ─── Settings: change these two lines ────────────────────────────────
const RIYA_URL = 'https://YOUR-RIYA-APP.vercel.app'; // your Sam admin app, no trailing slash
const GRAPH_VERSION = 'v23.0';                       // WhatsApp Cloud API version
// ─────────────────────────────────────────────────────────────────────

// What the menu buttons mean, phrased as the student would ask it.
const BUTTON_QUESTIONS = {
  courses: 'Which courses do you offer, and what are the fees?',
  admission: 'How does the admission process work and how do I apply?',
  counsellor: 'I would like a counsellor to call me back.',
};

const GREETING = /^(hi+|hello+|hey+|hii+|helo|namaste|namaskar|good (morning|afternoon|evening)|menu|start|help)[\s!.🙏👋]*$/i;

const results = [];
for (const item of $input.all()) {
  const body = item.json;
  // The trigger normally emits the "value" object; also accept the raw webhook shape.
  const value = body.messages || body.statuses ? body : body.entry?.[0]?.changes?.[0]?.value ?? body;
  const contact = value.contacts?.[0] ?? {};

  for (const msg of value.messages ?? []) { // delivery/read receipts have no messages: ignored
    let text = '';
    let buttonId = '';
    if (msg.type === 'text') text = msg.text?.body ?? '';
    if (msg.type === 'interactive') {
      const reply = msg.interactive?.button_reply ?? msg.interactive?.list_reply ?? {};
      buttonId = reply.id ?? '';
      text = BUTTON_QUESTIONS[buttonId] ?? reply.title ?? '';
    }
    if (msg.type === 'button') text = msg.button?.text ?? ''; // quick-reply on a template message
    text = text.trim().slice(0, 1500);

    const route = buttonId === 'menu' || GREETING.test(text) ? 'menu' : text ? 'ai' : 'unsupported';
    const phoneNumberId = value.metadata?.phone_number_id;

    results.push({
      json: {
        route,
        from: msg.from, // student's number, e.g. 919876543210
        name: contact.profile?.name ?? '',
        messageId: msg.id,
        type: msg.type,
        text,
        riyaUrl: RIYA_URL.replace(/\/+$/, ''),
        messagesUrl: 'https://graph.facebook.com/' + GRAPH_VERSION + '/' + phoneNumberId + '/messages',
      },
    });
  }
}
return results;

