={{ JSON.stringify({
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: $json.from,
  type: 'interactive',
  interactive: {
    type: 'button',
    body: {
      text: 'Hi' + ($json.name ? ' ' + $json.name.split(' ')[0] : '') + '! 👋 I\'m the admissions assistant.\n\nAsk me anything about our courses, fees, eligibility, scholarships, hostel or the admission process — in English or Hindi. Or tap an option below.'
    },
    footer: { text: 'Type your question anytime' },
    action: {
      buttons: [
        { type: 'reply', reply: { id: 'courses', title: 'Courses & fees' } },
        { type: 'reply', reply: { id: 'admission', title: 'How to apply' } },
        { type: 'reply', reply: { id: 'counsellor', title: 'Call me back' } }
      ]
    }
  }
}) }}

